<?php
/** Actual WordPress/PhoneKey/SQL policy checks, in a fresh owned local schema only. */
if ( PHP_SAPI !== 'cli' || ! defined( 'KIWE_V1_OWNED_DATABASE' ) || DB_NAME !== KIWE_V1_OWNED_DATABASE || ! preg_match( '/^kiwe_v1_[0-9]{8}_(editorial|store)$/D', DB_NAME ) ) throw new RuntimeException( 'Owned Kiwe1 fixture required.' );

function kiwe_v1_native_tests( bool $store ): array {
	global $wpdb;
	$checks = []; $GLOBALS['kiwe_v1_checks'] =& $checks;
