	$code = static fn( $value ) => is_wp_error( $value ) ? $value->get_error_code() : '';
	$normalize = static function( $value ) use ( &$normalize ) { if ( ! is_array( $value ) ) return $value; if ( ! array_is_list( $value ) ) ksort( $value, SORT_STRING ); return array_map( $normalize, $value ); };
	$same = static fn( $left, $right ) => serialize( $normalize( $left ) ) === serialize( $normalize( $right ) );
	if ( ! defined( 'DSA_OPTION_SETTINGS' ) ) define( 'DSA_OPTION_SETTINGS', 'dsa_settings' );
	if ( ! defined( 'DSA_VERSION' ) ) define( 'DSA_VERSION', '8.0.0-rc.452' );
	if ( ! defined( 'KIWE_REACT_WORKSPACE' ) ) define( 'KIWE_REACT_WORKSPACE', true );
