	wp_set_current_user( 1 );
	update_option( DSA\Access\Site_Owner_Service::OPTION, [ 'enabled'=>true, 'ownerId'=>1, 'dashboardMandatory'=>true, 'rankMath'=>'inline' ], false );
	(new DSA\Settings())->update( [ 'secure'=>[ 'enabled'=>true, 'protection_profile'=>'monitor' ] ] );
	$reader = wp_create_user( 'v1_reader', wp_generate_password( 32 ), 'reader-v1@example.test' );
	$second = wp_create_user( 'v1_second', wp_generate_password( 32 ), 'second-v1@example.test' );
	wp_update_user( [ 'ID'=>$reader, 'display_name'=>'Public Reader' ] );
	$post = wp_insert_post( [ 'post_type'=>'post', 'post_status'=>'publish', 'post_title'=>'Community context fixture', 'comment_status'=>'open', 'post_author'=>1 ] );
	$private = wp_insert_post( [ 'post_type'=>'post', 'post_status'=>'private', 'post_title'=>'Private fixture', 'comment_status'=>'open' ] );
	$comment = static function( int $target, string $name, string $text, array $extra = [] ): int {
		return (int) wp_insert_comment( $extra + [ 'comment_post_ID'=>$target, 'comment_author'=>$name, 'comment_author_email'=>'reader-v1@example.test', 'comment_content'=>$text, 'comment_approved'=>'1', 'user_id'=>$GLOBALS['v1_reader'] ] );
	}; $GLOBALS['v1_reader'] = $reader;
	$heart = $comment( $post, 'Public Reader', 'A genuine hearted comment.' );
	$pin = $comment( $post, 'Pinned Reader', 'A genuine pinned comment.' );
	$ordinary = $comment( $post, 'Other Reader', 'A liked comment.' );
	$hidden = $comment( $private, 'Private Reader', 'Never export private words.' );
	$held = $comment( $post, 'Held Reader', 'Held parent.', [ 'comment_approved'=>'0' ] );
	$reply = $comment( $post, 'Reply Reader', 'A reply with held ancestry.', [ 'comment_parent'=>$held ] );
	$staff = $comment( $post, 'Website Team', 'A team reply is not an endorsement.', [ 'user_id'=>1 ] );
	$email_name = $comment( $post, 'person@example.test', 'Contact-like public name must be masked.' );
