	update_comment_meta( $pin, $Reactions::PIN, '1' );
	$check( $Selection::testimonial_sources() === [ 'pinned'=>true, 'hearted'=>true, 'popular'=>false ], 'Default testimonial sources are explicit and popular is optional' );
	$items = array_column( $Selection::testimonials( 100 ), null, 'id' );
	$check( isset( $items[$heart],$items[$pin],$items[$email_name] ) && ! isset( $items[$hidden],$items[$reply],$items[$staff],$items[$ordinary] ), 'Projection excludes private targets, held ancestry, team endorsements and unselected sources' );
	$check( $items[$email_name]['name'] === 'Reader' && ! str_contains( wp_json_encode( $items ), '@' ), 'No email, phone or contact-derived identity becomes a testimonial author' );
	$check( $items[$heart]['target_id'] === $post && $items[$heart]['source_type'] === 'post' && ! isset( $items[$heart]['rating'] ), 'Native comment IDs and source IDs stay distinct; articles never acquire ratings' );
