	$check( DSA\Discussion\Discussion_Reaction_Store::set( $ordinary, $reader, 'like', true ), 'A native account like is recorded' );
	$profile['contentPlan']['testimonialSources']['popular'] = true; update_option( DSA\Onboarding\Design_Context_Profile_Service::OPTION_PROFILE, $profile, false );
	$popular = $Selection::testimonials();
	$check( count( $popular ) === 1 && $popular[0]['id'] === $ordinary && $popular[0]['likes'] === 1 && ! isset( $popular[0]['reports'],$popular[0]['user_id'] ), 'Popular-only curation uses actual likes without exposing actors or reports' );
	$check( DSA\Discussion\Discussion_Reaction_Store::set( $ordinary, $reader, 'like', false ) && $Selection::testimonials() === [], 'Removing the final like immediately revokes popular-only eligibility' );
	delete_option( DSA\Onboarding\Design_Context_Profile_Service::OPTION_PROFILE );
