	$check( in_array( $legacy, array_column( $Selection::testimonials(), 'id' ), true ), 'Legacy curated words remain readable before the explicit compatibility migration' );
	wp_set_current_user( $reader ); $check( is_wp_error( $Selection::migrate_testimonials() ), 'A subscriber cannot migrate curation' ); wp_set_current_user( 1 );
	$migration = $Selection::migrate_testimonials( 1 );
	$check( ! is_wp_error( $migration ) && $migration['processed'] === 1 && '1' === get_comment_meta( $legacy, $Reactions::HEART, true ) && ! metadata_exists( 'comment', $legacy, $Selection::TESTIMONIAL_META ) && get_comment( $legacy )->comment_content === 'Previously curated native words.', 'Bounded native migration keeps quote content and replaces only the legacy curation flag' );
	$check( $Selection::migrate_testimonials()['processed'] === 0, 'Curation migration is repeatable without duplicated records' );
	wp_set_comment_status( $heart, 'hold' ); $check( ! in_array( $heart, array_column( $Selection::testimonials(), 'id' ), true ), 'Revoking native approval removes testimonial eligibility' );
	if ( $store ) {
		$product = new WC_Product_Simple(); $product->set_name( 'Native testimonial product' ); $product->set_status( 'publish' ); $product->set_regular_price( '10' ); $pid = $product->save();
		$review = $comment( $pid, 'Product Reader', 'A native product review.', [ 'comment_type'=>'review' ] ); update_comment_meta( $review, 'rating', '4' ); update_comment_meta( $review, $Reactions::HEART, '1' );
		$projected = array_column( $Selection::testimonials(), null, 'id' );
		$check( isset( $projected[$review] ) && $projected[$review]['rating'] === 4 && $projected[$review]['source_type'] === 'product', 'Only a genuine native product review supplies its product rating' );
		update_option( DSA\Apps\Store_App_Service::OPTION, '0', false );
		$check( ! in_array( $review, array_column( $Selection::testimonials(), 'id' ), true ), 'Store-off excludes product testimonials while preserving their native records' );
		update_option( DSA\Apps\Store_App_Service::OPTION, '1', false );
	}
	$identity = DSA\Bricks\Form_Identity_Service::identity( [ '_attributes'=>[ [ 'name'=>'data-kiwe-form', 'value'=>'careers' ], [ 'name'=>'data-kiwe-form-label', 'value'=>'Careers enquiry' ] ], 'submissionFormName'=>'Different native fallback' ], 25, 'abc123' );
	$check( $identity['key'] === 'careers' && $identity['label'] === 'Careers enquiry' && $identity['postId'] === 25, 'Saved form attributes supply a stable identity and human label' );
	$stored = [ DSA\Bricks\Form_Identity_Service::META=>[ 'type'=>'kiwe-internal', 'value'=>wp_json_encode( $identity ) ] ];
	$check( DSA\Bricks\Form_Identity_Service::stored_identity( $stored, 25, 'abc123' ) === $identity && null === DSA\Bricks\Form_Identity_Service::stored_identity( $stored, 26, 'abc123' ), 'Historical form identity is bound to its native page/form pair' );
	$duplicate = DSA\Bricks\Form_Identity_Service::identity( [ '_attributes'=>[ [ 'name'=>'data-kiwe-form', 'value'=>'careers' ], [ 'name'=>'data-kiwe-form', 'value'=>'forged' ] ], 'submissionFormName'=>'Original form' ], 25, 'abc123' );
	$check( $duplicate['key'] === 'native-25-abc123' && $duplicate['label'] === 'Original form', 'Ambiguous identity attributes fall back to the native form owner' );
	$fields = DSA\Access\Form_Workspace_Service::public_fields( $stored + [ 'email'=>[ 'type'=>'email','value'=>'reader@example.test' ], 'password'=>[ 'type'=>'password','value'=>'synthetic secret' ] ], [] );
	$check( count( $fields ) === 1 && $fields[0]['label'] === 'email', 'Internal identity and passwords never appear as enquiry answers' );
	$policy = new DSA\Access\System_App_Workspace_Service();
	$read_request = new WP_REST_Request( 'GET', '/dsa/v1/workspace/system/auth' ); $read_request->set_url_params( [ 'app'=>'auth' ] ); $read_request->set_header( 'X-WP-Nonce', wp_create_nonce( 'wp_rest' ) );
	$check( $policy->permission( $read_request ), 'Included App read uses the current owner and native REST nonce' );
	$read_request->set_header( 'X-WP-Nonce', 'invalid' ); $check( ! $policy->permission( $read_request ), 'Invalid nonce cannot read included App settings' ); $read_request->set_header( 'X-WP-Nonce', wp_create_nonce( 'wp_rest' ) );
	$_SERVER['HTTP_ORIGIN'] = 'https://other.example.test'; $check( ! $policy->permission( $read_request ), 'Cross-origin settings read is denied' ); $_SERVER['HTTP_ORIGIN'] = home_url();
	$write_request = new WP_REST_Request( 'POST', '/dsa/v1/workspace/system/auth' ); $write_request->set_url_params( [ 'app'=>'auth' ] ); $write_request->set_header( 'X-WP-Nonce', wp_create_nonce( 'wp_rest' ) );
	$check( ! $policy->permission( $write_request ), 'Settings mutation requires the non-simple Kiwe mutation proof' ); $write_request->set_header( 'X-Kiwe-Mutation', '1' );
	$check( $policy->permission( $write_request ), 'Native nonce, same origin and mutation proof admit only the intended included App route' );
	$read_request->set_query_params( [ 'app'=>[ 'security' ] ] ); $check( $policy->read( $read_request )->get_data()['app'] === 'auth', 'Query/body input cannot replace the matched App identity' );
	$auth = pk_settings(); $auth['whatsapp_secret'] = DSA\Security\Secret_Store::encrypt( 'synthetic-initial-secret' ); $auth['future_native_extension'] = [ 'retained'=>'exact' ]; update_option( 'pk_settings_v3', $auth, false );
	$before = get_option( 'pk_settings_v3' ); $view = $policy->snapshot( 'auth' );
	$check( $view['values']['whatsapp_secret'] === '' && $view['secretSet']['whatsapp_secret'] && ! str_contains( wp_json_encode( $view ), 'synthetic-initial-secret' ) && ! str_contains( wp_json_encode( $view ), $before['whatsapp_secret'] ), 'Auth projection never returns the stored secret or ciphertext' );
	$changed = $view['values']['identifier_mode'] === 'email' ? 'email_or_phone' : 'email';
	$saved = $policy->update( 'auth', [ 'expected'=>$view['expected'], 'changes'=>[ 'identifier_mode'=>$changed ] ] );
	$expected = $before; $expected['identifier_mode'] = $changed;
	$check( ! is_wp_error( $saved ) && get_option( 'pk_settings_v3' ) === $expected, 'Auth partial save uses native validation and preserves every unrelated raw choice and secret' );
	$check( is_wp_error( $policy->update( 'auth', [ 'expected'=>$view['expected'], 'changes'=>[ 'identifier_mode'=>'email_and_phone' ] ] ) ) && get_option( 'pk_settings_v3' ) === $expected, 'Stale Auth review cannot overwrite newer choices' );
	$matrix = $policy->update( 'auth', [ 'expected'=>$saved['expected'], 'changes'=>[ 'role_matrix.subscriber.device_days'=>17 ] ] );
	$expected['role_matrix']['subscriber']['device_days'] = 17;
	$check( ! is_wp_error( $matrix ) && get_option( 'pk_settings_v3' ) === $expected, 'Changing one role rule preserves all other roles and native extension fields' );
	$check( is_wp_error( $policy->update( 'auth', [ 'expected'=>$matrix['expected'], 'changes'=>[ 'signup_role'=>'administrator' ] ] ) ), 'The App cannot make an ordinary signup an administrator' );
	$secret = $policy->update( 'auth', [ 'expected'=>$matrix['expected'], 'changes'=>[ 'whatsapp_secret'=>'synthetic-replacement-secret' ] ] );
	$after = get_option( 'pk_settings_v3' );
	$check( ! is_wp_error( $secret ) && DSA\Security\Secret_Store::decrypt( $after['whatsapp_secret'] ) === 'synthetic-replacement-secret' && $secret['values']['whatsapp_secret'] === '', 'Native Auth writer encrypts a replacement secret and returns only its configured state' );
	$empty = $policy->update( 'auth', [ 'expected'=>$secret['expected'], 'changes'=>[ 'whatsapp_secret'=>'' ] ] );
	$check( ! is_wp_error( $empty ) && get_option( 'pk_settings_v3' ) === $after, 'Blank secret input preserves the exact native encrypted value' );
	$secure = [ 'red_threshold'=>60, 'yellow_threshold'=>25, 'alert_repeat_window_mins'=>15, 'alert_hourly_limit'=>8, 'alert_delivery_policy'=>'actionable', 'future_native_extension'=>'exact', 'break_glass_slug'=>'synthetic-private-recovery-'.str_repeat( 'x', 32 ), 'v2_ai_key_enc'=>'synthetic-retained-provider-ciphertext' ];
	update_option( 'stp_settings', $secure, false ); $security = $policy->snapshot( 'security' );
	$check( ! str_contains( wp_json_encode( $security ), $secure['break_glass_slug'] ) && ! str_contains( wp_json_encode( $security ), $secure['v2_ai_key_enc'] ), 'Security projection never includes recovery secrets or provider ciphertext' );
	$security_save = $policy->update( 'security', [ 'expected'=>$security['expected'], 'changes'=>[ 'alert_hourly_limit'=>9 ] ] ); $secure['alert_hourly_limit'] = 9;
	$check( ! is_wp_error( $security_save ) && get_option( 'stp_settings' ) === $secure, 'Security alert edit preserves unrelated native policy, AI and recovery state' );
	$core_before = get_option( DSA_OPTION_SETTINGS );
	$guard = $policy->update( 'security', [ 'expected'=>$security_save['expected'], 'changes'=>[ 'kiwe.image_max_megapixels'=>45 ] ] );
	$core_expected = $core_before; $core_expected['secure']['image_max_megapixels'] = 45;
	$check( ! is_wp_error( $guard ) && $same( get_option( DSA_OPTION_SETTINGS ), $core_expected ) && get_option( 'stp_settings' ) === $secure, 'Core image guard uses the shared native sanitizer and selected-choice writer without rewriting SecureTrack policy' );
	$invalid = $policy->update( 'security', [ 'expected'=>$guard['expected'], 'changes'=>[ 'kiwe.image_max_megapixels'=>46, 'yellow_threshold'=>90 ] ] );
	$check( is_wp_error( $invalid ) && $same( get_option( DSA_OPTION_SETTINGS ), $core_expected ) && get_option( 'stp_settings' ) === $secure, 'A rejected mixed security save rolls back the earlier native option write' );
	$wpdb->query( 'START TRANSACTION' ); $wpdb->query( $wpdb->prepare( "INSERT INTO {$wpdb->options}(option_name,option_value,autoload) VALUES(%s,%s,'off')", 'v1_uncommitted_outer_marker', 'pending' ) );
	$nested = $policy->update( 'security', [ 'expected'=>$guard['expected'], 'changes'=>[ 'alert_hourly_limit'=>10 ] ] ); $wpdb->query( 'ROLLBACK' );
	$check( is_wp_error( $nested ) && ! get_option( 'v1_uncommitted_outer_marker', false ) && get_option( 'stp_settings' ) === $secure, 'App save refuses an outer native transaction without committing or rolling back someone else’s work' );
	$client_id = wp_create_user( 'v1_client', wp_generate_password( 32 ), 'client-v1@example.test' ); $client = new WP_User( $client_id ); $client->set_role( 'administrator' ); $client->add_cap( 'manage_options', false ); $client->add_cap( 'kiwe_manage_context' ); $client->add_cap( 'kiwe_manage_notification_policy' ); wp_set_current_user( $client_id );
	$client_auth = $policy->snapshot( 'auth' ); $client_security = $policy->snapshot( 'security' );
	$check( DSA\Apps\Required_App_Service::allowed( 'auth' ) && DSA\Apps\Required_App_Service::allowed( 'security' ) && ! current_user_can( 'manage_options' ), 'Client Administrator can use ordinary App controls without receiving technical WordPress capabilities' );
	$check( ! isset( $client_auth['values']['whatsapp_secret'],$client_auth['values']['whatsapp_key_id'],$client_auth['values']['protect_wp_admin'],$client_security['values']['csp_enabled'] ), 'Client projections omit providers, secrets, recovery and technical enforcement controls' );
	$auth_before_client = get_option( 'pk_settings_v3' );
	$check( is_wp_error( $policy->update( 'auth', [ 'expected'=>$client_auth['expected'], 'changes'=>[ 'role_matrix.administrator.login_mode'=>'none' ] ] ) ) && get_option( 'pk_settings_v3' ) === $auth_before_client, 'Client cannot weaken staff authentication through a hidden field' );
	$check( is_wp_error( DSA\PhoneKey\PhoneKey_Bridge::save_admin_settings( [ 'whatsapp_secret'=>'injected' ] ) ) && get_option( 'pk_settings_v3' ) === $auth_before_client, 'Native bridge independently denies provider changes to a non-technical client' );
	$client_save = $policy->update( 'auth', [ 'expected'=>$client_auth['expected'], 'changes'=>[ 'default_country_code'=>'+44' ] ] ); $auth_client_expected = $auth_before_client; $auth_client_expected['default_country_code'] = '+44';
	$check( ! is_wp_error( $client_save ) && get_option( 'pk_settings_v3' ) === $auth_client_expected, 'An ordinary client Auth edit preserves technical policy and secrets exactly' );
	$check( is_wp_error( $policy->update( 'security', [ 'expected'=>$client_security['expected'], 'changes'=>[ 'csp_enabled'=>true ] ] ) ), 'Client cannot submit technical Security controls' );
	wp_set_current_user( 1 );
	foreach ( DSA\Apps\Required_App_Service::IDS as $id ) { $card = DSA\Apps\Required_App_Service::card( $id ); $check( $card['enabled'] && $card['installed'] && ! $card['canChange'] && ! in_array( $id, DSA\Apps\Runtime_Contract::IDS, true ), ucfirst( $id ) . ' is included and outside every optional install/removal mutation' ); }
	$edit = DSA\Access\Contextual_Edit_Service::link( $post );
	$check( $edit && str_contains( $edit['url'], 'page=kiwe-posts' ) && str_contains( $edit['url'], 'post_id=' . $post ), 'Mandatory Menu Edit targets the actual post in Kiwe' );
	$owner_policy = get_option( DSA\Access\Site_Owner_Service::OPTION ); $owner_policy['dashboardMandatory'] = false; update_option( DSA\Access\Site_Owner_Service::OPTION, $owner_policy, false );
	$edit_native = DSA\Access\Contextual_Edit_Service::link( $post );
	$check( $edit_native && str_contains( $edit_native['url'], 'post.php?post=' . $post ) && str_contains( $edit_native['url'], 'action=edit' ), 'Optional Menu Edit preserves the native WordPress editor route' );
	if ( $store ) { $owner_policy['dashboardMandatory'] = true; update_option( DSA\Access\Site_Owner_Service::OPTION, $owner_policy, false ); $edit_product = DSA\Access\Contextual_Edit_Service::link( $pid ); $check( $edit_product && str_contains( $edit_product['url'], 'area=products' ) && str_contains( $edit_product['url'], 'edit=' . $pid ), 'Mandatory product Edit opens the appropriate native-product task' ); }
	wp_set_current_user( $reader );
	$check( ! DSA\Apps\Required_App_Service::allowed( 'auth' ) && ! DSA\Apps\Required_App_Service::allowed( 'security' ) && is_wp_error( $policy->update( 'auth', [ 'expected'=>'', 'changes'=>[ 'identifier_mode'=>'phone' ] ] ) ), 'A subscriber cannot read or mutate included App settings' );
	$check( DSA\Access\Contextual_Edit_Service::link( $post ) === null, 'An ordinary subscriber never receives a staff Edit launcher' );
	$preferences = new DSA\Notifications\Notification_Preference_Service( new DSA\Settings(), new DSA\Trust\Trust_Service() );
	foreach ( [ 'admin_form_submission','admin_app_activity','admin_campaign_status' ] as $topic ) $check( ! $preferences->topic_allowed_for_user( $reader, $topic ), 'Ordinary accounts cannot receive ' . $topic );
	wp_set_current_user( 1 ); $admin->add_cap( 'kiwe_manage_notification_policy' );
	foreach ( [ 'admin_form_submission','admin_app_activity','admin_campaign_status' ] as $topic ) $check( $preferences->topic_allowed_for_user( 1, $topic ), 'Eligible owner receives ' . $topic );
	kiwe_v1_forms_tests( $check );
	$check( $wpdb->last_error === '', 'No unexpected native SQL error remains' );
	return [ 'passed'=>true, 'checks'=>$checks, 'wordpress'=>$GLOBALS['wp_version'], 'woo'=>$store ? WC_VERSION : null, 'scope'=>'Native WordPress, unchanged PhoneKey, MariaDB policy/curation and actual Bricks form-save/SQL/inbox tests. Hosted rendering and browser checks remain separate.', 'cleanup'=>'Runner drops the entire explicitly owned schema.' ];
}
